return {
	-- Guide
	["A cloth hat in your late 20s: Zardeth's errand for any Alliance player pays warlocks this extra."] = "Ein Stoffhut in deinen späten Zwanzigern: Zardeths Auftrag für jeden Allianzspieler bringt Hexenmeistern diese Extra-Belohnung.",

